CREATE TABLE IF NOT EXISTS write_lock (id INT PRIMARY KEY) ENGINE=InnoDB;
INSERT IGNORE INTO write_lock(id) VALUES(1);
CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(200) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sessions (token VARCHAR(64) PRIMARY KEY, user_id BIGINT, expires BIGINT NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(100) PRIMARY KEY, value VARCHAR(1000) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS items (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(200) NOT NULL, barcode VARCHAR(80) COLLATE utf8mb4_bin NOT NULL UNIQUE, category VARCHAR(200) NOT NULL DEFAULT 'General', unit VARCHAR(200) NOT NULL DEFAULT 'pcs', cost BIGINT NOT NULL, price BIGINT NOT NULL, stock DECIMAL(18,3) NOT NULL DEFAULT 0, min_stock DECIMAL(18,3) NOT NULL DEFAULT 5, batch VARCHAR(200) NOT NULL DEFAULT '', serial VARCHAR(200) NOT NULL DEFAULT '') ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS parties (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(200) NOT NULL, kind VARCHAR(20) NOT NULL, phone VARCHAR(30) NOT NULL DEFAULT '', address VARCHAR(300) NOT NULL DEFAULT '') ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS documents (id BIGINT PRIMARY KEY AUTO_INCREMENT, number VARCHAR(40) NOT NULL UNIQUE, type VARCHAR(30) NOT NULL, date VARCHAR(10) NOT NULL, party_id BIGINT, account VARCHAR(100) NOT NULL, subtotal BIGINT NOT NULL, discount BIGINT NOT NULL, tax BIGINT NOT NULL, total BIGINT NOT NULL, paid BIGINT NOT NULL, cost BIGINT NOT NULL, notes VARCHAR(1000) NOT NULL DEFAULT '', category VARCHAR(200) NOT NULL DEFAULT '', reference_id BIGINT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(party_id) REFERENCES parties(id), FOREIGN KEY(reference_id) REFERENCES documents(id), INDEX(date), INDEX(party_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `lines` (id BIGINT PRIMARY KEY AUTO_INCREMENT, document_id BIGINT NOT NULL, item_id BIGINT, name VARCHAR(200) NOT NULL, category VARCHAR(200) NOT NULL, qty DECIMAL(18,3) NOT NULL, price BIGINT NOT NULL, cost BIGINT NOT NULL, discount BIGINT NOT NULL, tax BIGINT NOT NULL, total BIGINT NOT NULL, batch VARCHAR(200) NOT NULL DEFAULT '', serial VARCHAR(200) NOT NULL DEFAULT '', FOREIGN KEY(document_id) REFERENCES documents(id), FOREIGN KEY(item_id) REFERENCES items(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ledger (id BIGINT PRIMARY KEY AUTO_INCREMENT, document_id BIGINT, date VARCHAR(10) NOT NULL, account VARCHAR(100) NOT NULL, debit BIGINT NOT NULL DEFAULT 0, credit BIGINT NOT NULL DEFAULT 0, party_id BIGINT, memo VARCHAR(200) NOT NULL DEFAULT '', FOREIGN KEY(document_id) REFERENCES documents(id), FOREIGN KEY(party_id) REFERENCES parties(id), INDEX(date), INDEX(account)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS movements (id BIGINT PRIMARY KEY AUTO_INCREMENT, document_id BIGINT, item_id BIGINT, date VARCHAR(10) NOT NULL, qty DECIMAL(18,3) NOT NULL, cost BIGINT NOT NULL, FOREIGN KEY(document_id) REFERENCES documents(id), FOREIGN KEY(item_id) REFERENCES items(id), INDEX(date)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit (id BIGINT PRIMARY KEY AUTO_INCREMENT, date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, action VARCHAR(100) NOT NULL, detail VARCHAR(1000) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS storefront_requests (id BIGINT PRIMARY KEY AUTO_INCREMENT, submission_key VARCHAR(64) NOT NULL UNIQUE, submission_hash VARCHAR(64) NOT NULL, code VARCHAR(30) NOT NULL UNIQUE, role VARCHAR(20) NOT NULL, contact_name VARCHAR(200) NOT NULL, phone VARCHAR(30) NOT NULL, address VARCHAR(300) NOT NULL DEFAULT '', notes VARCHAR(1000) NOT NULL DEFAULT '', payload MEDIUMTEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', order_id BIGINT, document_id BIGINT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at VARCHAR(30) NOT NULL DEFAULT '', FOREIGN KEY(order_id) REFERENCES documents(id), FOREIGN KEY(document_id) REFERENCES documents(id), INDEX(status), INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS store_customers(id BIGINT PRIMARY KEY AUTO_INCREMENT,customer_key VARCHAR(36) NOT NULL UNIQUE,name VARCHAR(200) NOT NULL,phone VARCHAR(30) NOT NULL,login VARCHAR(80) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',segment VARCHAR(30) NOT NULL DEFAULT 'public') ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS store_customer_sessions(token VARCHAR(64) PRIMARY KEY,customer_id BIGINT NOT NULL,expires BIGINT NOT NULL,FOREIGN KEY(customer_id) REFERENCES store_customers(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS store_order_links(id BIGINT PRIMARY KEY AUTO_INCREMENT,request_id BIGINT NOT NULL UNIQUE,customer_key VARCHAR(36) NOT NULL,FOREIGN KEY(request_id) REFERENCES storefront_requests(id),INDEX(customer_key)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS store_settings(id INT PRIMARY KEY,payload MEDIUMTEXT NOT NULL) ENGINE=InnoDB;
